async function sendInferenceRequest(featureArray) {
  const resultDisplay = document.getElementById("prediction-result");
  resultDisplay.innerText = "Computing inference...";

  try {
    const res = await fetch("http://127.0.0.1:8000/predict", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ features: featureArray })
    });

    if (!res.ok) throw new Error(`HTTP error code: ${res.status}`);

    const data = await res.json();
    resultDisplay.innerHTML = `
      <strong>Label:</strong> ${data.prediction_label} <br>
      <strong>Confidence:</strong> ${(data.probability * 100).toFixed(1)}% <br>
      <strong>Latency:</strong> ${data.latency_ms} ms
    `;
  } catch (err) {
    resultDisplay.innerText = `Network Error: ${err.message}`;
  }
}
